fn from_params<T: serde::de::DeserializeOwned>(params: serde_json::Value) -> Result<T, CallError> {
    serde_json::from_value(params).map_err(|error| crate::validation(&error.to_string()))
}

fn to_result<T: Serialize>(answer: Result<T, CallError>) -> Result<serde_json::Value, CallError> {
    let value = answer?;
    serde_json::to_value(value).map_err(|error| crate::protocol("unserializable_result", &error.to_string()))
}

/// Calls the `Host` method a driver's request names.
pub(crate) async fn dispatch_host(host: &dyn Host, method: &str, params: serde_json::Value) -> Result<serde_json::Value, CallError> {
    match method {
        "host/config.get" => to_result(host.config_get(from_params(params)?).await),
        "host/secrets.get" => to_result(host.secrets_get(from_params(params)?).await),
        "host/secrets.set" => to_result(host.secrets_set(from_params(params)?).await),
        "host/secrets.delete" => to_result(host.secrets_delete(from_params(params)?).await),
        "host/process.spawn" => to_result(host.process_spawn(from_params(params)?).await),
        "host/process.resolveExecutable" => to_result(host.process_resolve_executable(from_params(params)?).await),
        "host/attachments.resolve" => to_result(host.attachments_resolve(from_params(params)?).await),
        "host/attachments.extractText" => to_result(host.attachments_extract_text(from_params(params)?).await),
        "host/callbacks.register" => to_result(host.callbacks_register(from_params(params)?).await),
        "host/hostTools.mcpServerFor" => to_result(host.host_tools_mcp_server_for(from_params(params)?).await),
        "host/hostTools.callDynamicTool" => to_result(host.host_tools_call_dynamic_tool(from_params(params)?).await),
        "host/background.shouldRun" => to_result(host.background_should_run(from_params(params)?).await),
        "host/coordination.acquire" => to_result(host.coordination_acquire(from_params(params)?).await),
        "host/coordination.release" => to_result(host.coordination_release(from_params(params)?).await),
        "host/diagnostics.log" => to_result(host.diagnostics_log(from_params(params)?).await),
        "host/telemetry.track" => to_result(host.telemetry_track(from_params(params)?).await),
        "host/ids.derive" => to_result(host.ids_derive(from_params(params)?).await),
        "host/process.write" => to_result(host.process_write(from_params(params)?).await),
        "host/process.closeStdin" => to_result(host.process_close_stdin(from_params(params)?).await),
        "host/process.kill" => to_result(host.process_kill(from_params(params)?).await),
        _ => Err(crate::unsupported(method, "no such host method")),
    }
}
